# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import uncovered_gaps
from hourglass.errors import ProjectError

OPEN = parse_span("09:00-17:00")


class GapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        spans = [parse_span("09:00-12:00"), parse_span("13:00-17:00")]
        self.assertEqual(uncovered_gaps(spans, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_edges_and_overlaps(self):
        spans = [parse_span("10:00-11:00"), parse_span("10:30-12:00")]
        self.assertEqual(
            uncovered_gaps(spans, OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 12:00-17:00 (300 min)"]
        )

    def test_no_workers_leaves_whole_day(self):
        self.assertEqual(uncovered_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_full_cover_has_no_gaps(self):
        self.assertEqual(uncovered_gaps([OPEN], OPEN), [])

    def test_outside_opening_hours_raises(self):
        with self.assertRaises(ProjectError):
            uncovered_gaps([parse_span("08:00-10:00")], OPEN)
